mapper.select:
select

from corgi_vlog v left join corgi_user_detail d on d.user_id = v.user_id
where v.ctime <=#{ctime}
and not exists(select 1 from corgi_feed_${index} where user_id = #{userId} and `feed` = activity_id)
and v.user_id != #{userId}
order by like_count desc limit 20

select

from corgi_vlog v
where activity_id = #{activityId}

select
from corgi_vlog v where not exists(select 1 from corgi_feed_${index} where user_id = #{vlog.userId})
and ctime like '${vlog.ctime}%'
order by v.like_count desc limit #{size}

select

from corgi_vlog v
where v.user_id in (select follow_user_id from corgi_user_follow where user_id = #{userId})
and v.ctime <=#{ctime}
limit #{start}, #{size}
